#!/usr/bin/env python3
"""TEHNOKOVSH publisher: 75 scheduled posts, branded images on 10 evenings.
Replaces only publish.py; keeps existing posts.json, sent.json and workflow.
"""
import argparse
import base64
import datetime as dt
import io
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import urllib.error
import urllib.request
import uuid

ROOT = Path(__file__).resolve().parent
POSTS = ROOT / "data" / "posts.json"
STATE = ROOT / "data" / "sent.json"
CHANNEL = "@kvadro_biznes"
MOSCOW = dt.timezone(dt.timedelta(hours=3))
START = dt.datetime(2026, 11, 10, tzinfo=MOSCOW)
END = dt.datetime(2026, 12, 10, tzinfo=MOSCOW)
# A real TEHNOKOVSH logo supplied earlier in this conversation.
# We deliberately do NOT present generic photos or low-resolution PDF thumbnails as proof of transactions.
BRAND_IMAGE_B64 = """"""
IMAGE_DAYS = {1, 4, 7, 10, 13, 16, 19, 22, 25, 28}


def git(*args):
    return subprocess.run(["git", *args], cwd=ROOT, check=True, capture_output=True, text=True)


def save_state(state):
    STATE.write_text(json.dumps(state, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    git("config", "user.name", "tehnokovsh-publisher[bot]")
    git("config", "user.email", "41898282+github-actions[bot]@users.noreply.github.com")
    git("add", "data/sent.json")
    git("commit", "-m", "Record Telegram publication")
    git("push", "origin", "HEAD:main")


def request_telegram(token, method, payload, photo=None):
    url = "https://api.telegram.org/bot" + token + "/" + method
    if photo is None:
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        headers = {"Content-Type": "application/json"}
    else:
        boundary = "----tehnokovsh" + uuid.uuid4().hex
        parts = []
        for key, value in payload.items():
            parts.append((f"--{boundary}\r\nContent-Disposition: form-data; name=\"{key}\"\r\n\r\n{value}\r\n").encode("utf-8"))
        parts.append((f"--{boundary}\r\nContent-Disposition: form-data; name=\"photo\"; filename=\"tehnokovsh.jpg\"\r\nContent-Type: image/jpeg\r\n\r\n").encode("utf-8"))
        parts.append(photo)
        parts.append((f"\r\n--{boundary}--\r\n").encode("utf-8"))
        body = b"".join(parts)
        headers = {"Content-Type": "multipart/form-data; boundary=" + boundary}
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=45) as res:
            response = json.load(res)
    except urllib.error.HTTPError as exc:
        # Never print full URL, which contains bot token.
        print("Telegram HTTP error:", exc.code, file=sys.stderr)
        raise SystemExit(1)
    except Exception as exc:
        print("Telegram connection error:", type(exc).__name__, file=sys.stderr)
        raise SystemExit(1)
    if not response.get("ok"):
        print("Telegram API reported failure", file=sys.stderr)
        raise SystemExit(1)
    return response["result"]["message_id"]


def send(token, item):
    day = int(item["id"][1:3])
    is_brand = item["id"].endswith("-19") and day in IMAGE_DAYS
    content = item["text"]
    if is_brand and len(content) <= 1024:
        photo = base64.b64decode(BRAND_IMAGE_B64)
        return request_telegram(token, "sendPhoto", {"chat_id": CHANNEL, "caption": content}, photo=photo)
    return request_telegram(token, "sendMessage", {"chat_id": CHANNEL, "text": content, "disable_web_page_preview": True})


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--validate", action="store_true")
    args = parser.parse_args()
    posts = json.loads(POSTS.read_text(encoding="utf-8"))
    assert len(posts) == 75, "Expected exactly 75 posts"
    assert len({p["id"] for p in posts}) == 75, "Duplicate post IDs"
    for item in posts:
        stamp = dt.datetime.fromisoformat(item["at"])
        assert stamp.utcoffset() == dt.timedelta(hours=3) and START <= stamp < END
        assert len(item["text"]) <= 4096
    if args.validate:
        print("VALID: 75 posts, 30 days, 10 brand-image evenings, Moscow timezone")
        return
    now = dt.datetime.now(dt.timezone.utc).astimezone(MOSCOW)
    if now < START:
        print("Waiting until campaign start:", START.isoformat())
        return
    if now >= END:
        print("Campaign period completed")
        return
    state = json.loads(STATE.read_text(encoding="utf-8"))
    sent = state["sent"]
    due = sorted((p for p in posts if p["id"] not in sent and dt.datetime.fromisoformat(p["at"]) <= now), key=lambda p: p["at"])
    print("Moscow time:", now.isoformat(), "due:", len(due), "sent:", len(sent))
    if args.dry_run:
        for item in due[:5]:
            print("DUE", item["id"], item["at"])
        return
    token = os.environ.get("TELEGRAM_BOT_TOKEN")
    if not token:
        raise RuntimeError("Missing TELEGRAM_BOT_TOKEN secret")
    for item in due[:5]:
        mid = send(token, item)
        sent[item["id"]] = {"message_id": mid, "sent_at": dt.datetime.now(MOSCOW).isoformat()}
        save_state(state)
        print("Published", item["id"], "message_id", mid)
        time.sleep(1)


if __name__ == "__main__":
    main()
